const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const a = data.slice(1, 1 + n);

const idx = Array.from({ length: n }, (_, i) => i);
idx.sort((i, j) => a[j] - a[i]);

const active = new Uint8Array(n + 2);
let k = 0;
let maxK = 0;
let i = 0;

while (i < n) {
    const h = a[idx[i]];
    let j = i;

    while (j < n && a[idx[j]] === h) {
        const p = idx[j] + 1;
        active[p] = 1;

        const left = active[p - 1];
        const right = active[p + 1];

        if (left && right) {
            k--;
        } else if (!left && !right) {
            k++;
        }

        j++;
    }

    if (k > maxK) maxK = k;
    i = j;
}

console.log(maxK + 1);
